(function(){
  const kindMap={input:['dataset',0,'数据集'],initial:['environment',3,'环境模板'],script:['simulator',1,'用户模拟器'],reference:['reference',0,'参考与金标']};
  for(const [resourceKind,items] of Object.entries(CaseContracts.seedAssets))for(const r of items){const [kind,group,type]=kindMap[resourceKind];if(!assets.some(a=>a.id===r.id))assets.push({id:r.id,version:r.version,name:r.name,kind,group,type,status:'已发布',owner:'示例资产',targets:[r.target],source:'人工构造业务样例 · 开发用途',qualification:'DEMO_ONLY',content:r.text||(r.samples||[]).map(x=>x.id+'\n'+x.text).join('\n\n'),caseResource:{...r,resourceKind},count:r.samples?r.samples.length+'条示例样本':'固定示例版本',demandAsset:true});}
  for(const t of Object.values(CaseContracts.templates)){
    if(!assets.some(a=>a.id===t.id))assets.push({id:t.id,version:t.version,kind:'scenario',group:1,type:'场景模板',name:t.name,status:'已发布',owner:'示例资产',targets:[t.target],qualification:'DEMO_ONLY',count:'可选参数范围与强制规则',source:'PRD 3.3结构的人工构造示例',content:t.goal+'\n'+t.rules.map(r=>r.name).join('\n'),demandAsset:true});
    const exampleId='CASE-EXAMPLE-'+t.key.toUpperCase();if(!assets.some(a=>a.id===exampleId)){const d=CaseContracts.example(t.key);d.caseId=exampleId;d.version='v1.0';const spec=CaseContracts.legacySpec(d,CaseContracts.catalog(S));assets.push({id:exampleId,version:d.version,name:d.name,kind:'case',type:'评测用例',group:1,status:'已发布',owner:'示例资产',targets:[d.target],qualification:'DEMO_ONLY',count:'PRD结构示例',source:d.source,caseSpec:spec,content:CaseAuthoring.content(spec),demandAsset:true});}
    for(const r of t.rules)if(!assets.some(a=>a.id===r.id))assets.push({id:r.id,version:r.version,kind:'check',group:2,type:'检查包',name:r.name,status:'已发布',owner:'示例资产',targets:[t.target],qualification:'DEMO_ONLY',count:'示例检查规则（断言）',source:'模板 '+t.id+' @ '+t.version,content:r.subject+' '+r.op+' '+r.value+'\n证据：'+r.evidence,demandAsset:true});
  }
  pages['case-builder']=()=>'<div id="case-design-review"><div class="ev-page" id="ev-screen"></div><div id="ev-notification" aria-live="polite"></div><details class="ev-design"><summary>PRD依据与交互边界</summary><ul><li>对应PRD 3.3 AS-C01～AS-C04：具体用例与场景模板、数据、初始状态、脚本、断言分别管理，正式运行冻结引用。</li><li>本交互稿支持实际内容保存、版本化引用、完整性与规则冲突检查、CSV／XLSX／JSONL解析及批量候选生成。记录保存在当前浏览器。</li><li>实际动作配置可保存为草稿；旧用例的步骤说明不会自动转成执行指令。真实执行器兼容验证、正式能力验证与真实试运行尚未接入。开发示例中的阈值不代表生产标准。</li><li>待明确的细节：执行动作协议、事件字段对应关系、等待与脚本的先后／并行语义、统计粒度、批次部分提交、例外审批规则及专业资格服务；PRD已明确的最低字段和规则继承不再列为待澄清。</li></ul></details></div>';
  const originalRender=render;render=function(){originalRender();if(S.route==='case-builder')CaseWorkbench.mount();};
  caseBuilderOpen=options=>CaseWorkbench.open(options||{});
  caseBulkOpen=()=>CaseWorkbench.open({bulk:true});
  const originalMissing=CaseAuthoring.missing;
  CaseAuthoring.missing=spec=>spec?.prd?CaseContracts.validate(spec.prd,CaseContracts.catalog(S)):originalMissing(spec);
  const originalSummary=caseBuilderSummary;
  caseBuilderSummary=function(a){if(!a.caseSpec?.prd)return originalSummary(a);const d=a.caseSpec.prd,c=a.caseSpec.contract;return '<div class="cb-summary"><h3>PRD结构化用例</h3><dl>'+[['目标',d.goal],['适用条件',d.applicable],['输入版本',c.input_refs.map(x=>x.id+' @ '+x.version+' / '+(x.sample_id||'实际输入内容')).join('\n')],['初始状态',c.initial_state_ref?c.initial_state_ref.id+' @ '+c.initial_state_ref.version:'待补齐'],['执行步骤与交互',d.steps.join('\n')],['允许的最终状态',d.allowed],['禁止发生的行为或变更',d.forbidden],['断言版本',d.rules.map(x=>x.id+' @ '+x.version+' · '+x.name+(x.mandatory?'（强制）':'')).join('\n')],['超时／误差',d.timeout+'秒 / '+d.window],['例外',d.exception?'待确认：'+d.exception.reason:'无'],['证据不足时如何处理','UNKNOWN；已证实的失败保持失败（FAIL）']].map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+esc(v||'待补齐')+'</dd></div>').join('')+'</dl>'+notice('用例定义与实际执行结果分开。正式运行仍需执行、环境与评分能力的专业验证。','','file')+'</div>';};
  if(new URLSearchParams(location.search).get('view')==='case-builder'&&!scene)CaseWorkbench.open();
  else if(S.route==='case-builder')render();
})();
